// What this run will read, decided once and carried by every later node.
//
// The webhook answers immediately (responseMode: onReceived), so nothing
// downstream can report a problem to the caller. Everything that can be
// wrong with the request is therefore caught here and thrown, which the
// error trigger turns into a "failed" callback the Content Admin can show —
// a build that dies silently leaves a row saying "running" for ever.
const body = $input.first().json.body || {};

const buildId    = (body.build_id || '').trim();
const courseId   = (body.course_id || '').trim();
const collection = (body.collection || '').trim();
const agents     = Array.isArray(body.agents) ? body.agents.map(Number).filter(n => n > 0) : [];

if (!buildId)    throw new Error('This run carries no build_id, so nothing could be reported back and the Content Admin would wait for ever.');
if (!courseId)   throw new Error('This run names no course, so its concepts would belong to none.');
if (!collection) throw new Error('This run names no collection, so there is nothing to read.');
if (!agents.length) throw new Error('No agent is included in the map, so there is no material to read.');

// The Content Admin's own limit, repeated here because this workflow decides
// how many candidates to keep and a list that exceeded it would be refused
// on arrival, after every call had been paid for.
const MAX_CONCEPTS = 500;

// One slice of material per model call. Well below any provider's context
// limit, and small enough that a slice which fails can be retried on its own
// rather than costing a whole document.
const SLICE_CHARS = 40000;
// Per section, so a 400-character excerpt plus its headings.
const EXCERPT_CHARS = 400;

return [{
  json: {
    buildId, courseId, collection, agents,
    courseName: (body.course_name || '').trim() || courseId,
    language: (body.language || 'en').trim(),
    MAX_CONCEPTS, SLICE_CHARS, EXCERPT_CHARS,
    adminUrl: 'http://smartrag-content-admin:5000',
    startedAt: new Date().toISOString(),
  }
}];

// The corpus, cut into pieces a model can be asked about one at a time.
//
// The map covers a whole course across up to ten agents, so the material is
// far larger than any single prompt: measured on the test installation, four
// works came to 257 sections and ~113k characters, and the target is ten
// agents' worth. The way out is not a bigger prompt. Concepts are found
// *locally* — a concept is in a document, and finding it needs that document
// and nothing else — so extraction happens per slice and the corpus never has
// to fit anywhere at once. Only the prerequisite pass needs a global view, and
// that one reads the concept list, which is capped, not the material.
//
// One entry per section rather than per chunk: neighbouring chunks of the same
// section repeat each other, and the budget is better spent on the shape of
// the course.
const plan = $('Plan the run').first().json;
const rows = (($input.first().json?.data?.Get || {})[plan.collection]) || [];

if (!rows.length) {
  throw new Error(
    'This course has no indexed material for the agents included in the map. ' +
    'A concept map proposed from nothing would be the model’s general ' +
    'knowledge of the subject, presented as this course’s.');
}

// Order within a document is what makes "comes before" mean anything, and
// Weaviate returns no order of its own.
rows.sort((a, b) => {
  const t = String(a.source_title || '').localeCompare(String(b.source_title || ''));
  if (t !== 0) return t;
  return (Number.isInteger(a.chunk_index) ? a.chunk_index : 0)
       - (Number.isInteger(b.chunk_index) ? b.chunk_index : 0);
});

const docs = new Map();   // source_file -> {title, file, entries[]}
const seen = new Set();

for (const row of rows) {
  const file = (row.source_file || '').trim();
  if (!file) continue;                 // provenance keys on source_file
  const title   = (row.source_title || '').trim() || file;
  const chapter = (row.chapter_title || '').trim();
  const section = (row.section || '').trim();
  const marker  = `${file}::${chapter}::${section}`;
  if (seen.has(marker)) continue;      // one entry per section, not per chunk
  seen.add(marker);

  const excerpt = String(row.text || '').replace(/\s+/g, ' ').trim().slice(0, plan.EXCERPT_CHARS);
  if (!excerpt) continue;

  if (!docs.has(file)) docs.set(file, { title, file, entries: [] });
  docs.get(file).entries.push({
    chapter, section,
    section_id: (row.section_id || '').trim(),
    excerpt,
  });
}

// Slice each document on its own. A slice never spans two works: the model is
// asked "what does this text introduce", and mixing two subjects in one
// question is how a concept ends up attributed to the wrong one — which
// provenance would then record as fact.
const slices = [];
for (const doc of docs.values()) {
  let current = [];
  let used = 0;
  const flush = () => {
    if (!current.length) return;
    slices.push({
      buildId: plan.buildId, courseId: plan.courseId, courseName: plan.courseName,
      language: plan.language, adminUrl: plan.adminUrl,
      source_file: doc.file, source_title: doc.title,
      part: slices.filter(s => s.source_file === doc.file).length + 1,
      entries: current,
    });
    current = [];
    used = 0;
  };
  for (const e of doc.entries) {
    const cost = e.chapter.length + e.section.length + e.section_id.length + e.excerpt.length + 8;
    if (used + cost > plan.SLICE_CHARS && current.length) flush();
    current.push(e);
    used += cost;
  }
  flush();
}

// Each slice says how many there are in total, so the last one can tell the
// merge step it is the last without the loop having to carry state.
const total = slices.length;
return slices.map((s, i) => ({ json: { ...s, sliceIndex: i + 1, sliceTotal: total,
                                       documents: docs.size, sections: seen.size } }));

// ── One text completion, against whichever provider is configured ──────────
// The same six-way dispatch as content-admin/llm_client.py and the image
// description in ingest-document.json — same endpoints, headers and auth,
// text only. Copied rather than imported because n8n Code nodes cannot share
// a module; kept identical so a provider that works for one feature works for
// all of them.
async function complete(systemPrompt, userPrompt, maxTokens) {
  const provider = ($env.LLM_PROVIDER || '').trim();
  const apiKey   = $env.LLM_API_KEY || '';
  const model    = $env.LLM_MODEL_STRONG || '';
  const baseUrl  = $env.LLM_BASE_URL || '';
  // No fallback: calling a different vendor than the configured one produces
  // an auth error that points away from the real problem, an empty variable.
  if (!provider) throw new Error('LLM_PROVIDER is empty in .env.');
  if (!apiKey)   throw new Error('LLM_API_KEY is empty in .env.');
  if (!model)    throw new Error('LLM_MODEL_STRONG is empty in .env.');

  let url, headers, body, extractText, finishReason;

  if (provider === 'anthropic') {
    url = 'https://api.anthropic.com/v1/messages';
    headers = { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' };
    body = { model, max_tokens: maxTokens, system: systemPrompt,
             messages: [{ role: 'user', content: userPrompt }] };
    extractText  = (d) => (d.content || []).find(b => b.type === 'text')?.text || '';
    finishReason = (d) => d.stop_reason || '';
  } else if (provider === 'google') {
    url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`;
    headers = { 'x-goog-api-key': apiKey, 'Content-Type': 'application/json' };
    body = { systemInstruction: { parts: [{ text: systemPrompt }] },
             contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
             generationConfig: { maxOutputTokens: maxTokens } };
    extractText  = (d) => d?.candidates?.[0]?.content?.parts?.[0]?.text || '';
    finishReason = (d) => d?.candidates?.[0]?.finishReason || '';
  } else if (provider === 'cohere') {
    url = 'https://api.cohere.com/v2/chat';
    headers = { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' };
    body = { model, max_tokens: maxTokens, stream: false,
             messages: [{ role: 'system', content: systemPrompt },
                        { role: 'user', content: userPrompt }] };
    extractText  = (d) => d?.message?.content?.[0]?.text || '';
    finishReason = (d) => d?.finish_reason || '';
  } else {
    if (provider === 'openai') url = 'https://api.openai.com/v1/chat/completions';
    else if (provider === 'mistral') url = 'https://api.mistral.ai/v1/chat/completions';
    else if (provider === 'openrouter') url = 'https://openrouter.ai/api/v1/chat/completions';
    else if (provider === 'custom') url = `${(baseUrl || '').replace(/\/$/, '')}/chat/completions`;
    else throw new Error(`Unknown LLM_PROVIDER: ${provider}`);
    headers = { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' };
    body = { model, messages: [{ role: 'system', content: systemPrompt },
                               { role: 'user', content: userPrompt }] };
    // OpenAI rejects max_tokens outright on current models; the others still
    // want it. Same split as llm_client.py.
    if (provider === 'openai') body.max_completion_tokens = maxTokens;
    else body.max_tokens = maxTokens;
    extractText  = (d) => d?.choices?.[0]?.message?.content || '';
    finishReason = (d) => d?.choices?.[0]?.finish_reason || '';
  }

  const raw = await this.helpers.request({ method: 'POST', url, headers,
                                           body: JSON.stringify(body), json: false });
  const data = JSON.parse(raw);
  const text = (extractText(data) || '').trim();
  if (!text) {
    // An empty answer is a failure where it happens. Measured on the test
    // installation: a reasoning model spent the whole budget thinking and
    // returned an empty string with finish_reason "length", which the API
    // calls a success — and the emptiness was then reported several layers
    // away as something that had not happened.
    const why = finishReason(data) || 'not stated';
    throw new Error(`The model returned an empty answer (finish reason: ${why}). ` +
      (/len|max_token/i.test(why)
        ? `The budget of ${maxTokens} tokens was spent before any text was written.`
        : ''));
  }
  return text;
}

// Models wrap JSON in a fence often enough that stripping it is leniency
// about the wrapper, not about the format.
function parseJson(text, what) {
  let raw = text.trim();
  const fence = raw.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/);
  if (fence) raw = fence[1];
  try {
    return JSON.parse(raw);
  } catch (e) {
    throw new Error(`${what}: the model did not return valid JSON (${e.message}). ` +
                    `First 200 characters: ${raw.slice(0, 200)}`);
  }
}
// ── One slice of one document → the concepts it introduces ─────────────────
// Runs once per slice, because N8N_RUNNERS_TASK_TIMEOUT is 1800 seconds and a
// single node looping over forty documents would be killed halfway with
// nothing to show. One slice per execution also means a slice that fails is
// the only thing retried.
const slice = $input.first().json;
const plan  = $('Plan the run').first().json;

const material = slice.entries.map(e => {
  const head = [e.chapter, e.section].filter(Boolean).join(' · ');
  const id   = e.section_id ? ` [${e.section_id}]` : '';
  return `## ${head || '(no heading)'}${id}\n${e.excerpt}`;
}).join('\n\n');

const systemPrompt =
  'You extract the concepts a piece of university course material teaches. ' +
  'You answer with JSON and nothing else: no explanation, no commentary, no ' +
  'code fence.';

const userPrompt =
  `Below is part of "${slice.source_title}" from the course ` +
  `"${slice.courseName}" — one entry per section, each with a short excerpt.\n\n` +
  'Name the concepts this material *teaches*. A concept is something a ' +
  'student has to understand: a term, a model, a method, a distinction. Not ' +
  'a heading, not an author, not the name of the document, and not a topic ' +
  'so broad it covers the whole course.\n\n' +
  'For each one give:\n' +
  '  "name"        — as this material calls it, in its own language\n' +
  '  "description" — one sentence, what a student needs to grasp\n' +
  '  "chapter"     — the chapter or section it is introduced in, if stated\n' +
  '  "section_id"  — the section number, if the material gives one\n\n' +
  'Prefer fewer, well-chosen concepts to an exhaustive list. If this part ' +
  'introduces nothing new — a foreword, a bibliography, a table of ' +
  'contents — answer with an empty list; that is a useful answer, not a ' +
  'failure.\n\n' +
  'Answer exactly:\n' +
  '{"concepts": [{"name": "...", "description": "...", "chapter": "...", "section_id": "..."}]}\n\n' +
  `--- Material ---\n${material}\n--- end ---`;

const answer = await complete.call(this, systemPrompt, userPrompt, 8192);
const parsed = parseJson(answer, `Extracting from "${slice.source_title}"`);

const out = [];
for (const c of (parsed.concepts || [])) {
  const name = String(c?.name ?? '').trim();
  if (!name || name.length > 120) continue;
  out.push({
    name,
    description: String(c?.description ?? '').trim().slice(0, 500) || null,
    chapter: String(c?.chapter ?? '').trim() || null,
    section_id: String(c?.section_id ?? '').trim() || null,
    // Provenance, attached here and nowhere else. The model is asked about
    // titles it can read; the file path is what the graph stores, and this
    // is the only place that knows both.
    source_file: slice.source_file,
    source_title: slice.source_title,
  });
}

return [{ json: { sliceIndex: slice.sliceIndex, sliceTotal: slice.sliceTotal,
                  source_file: slice.source_file, concepts: out } }];

// ── Every slice's candidates, made into one vocabulary ─────────────────────
// The same concept turns up in several documents, and that is the useful
// case, not the awkward one: it tells us the concept is central and it gives
// it more than one citation, which is what lets it survive one of its
// documents being deleted.
//
// Merging is mechanical here — exact match after normalising case, spacing
// and trailing punctuation. Near-synonyms ("Medienkompetenz" /
// "Medienkompetenzen") are deliberately *not* merged by guesswork: a wrong
// merge silently destroys a distinction the course draws, and neither a
// string distance nor a model is right often enough to do that unattended.
// They stay separate and a person can merge them in the review.
const plan  = $('Plan the run').first().json;
const items = $input.all().map(i => i.json);

const norm = (s) => String(s || '').toLowerCase()
  .normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[\s\u00a0]+/g, ' ')
  .replace(/[.,;:!?]+$/, '')
  .trim();

const byKey = new Map();
let candidates = 0;

for (const item of items) {
  for (const c of (item.concepts || [])) {
    candidates++;
    const key = norm(c.name);
    if (!key) continue;
    let entry = byKey.get(key);
    if (!entry) {
      entry = { name: c.name, description: c.description, chapter: c.chapter,
                section_id: c.section_id, sources: [], titles: [], mentions: 0 };
      byKey.set(key, entry);
    }
    entry.mentions++;
    // First non-empty wins for the prose fields: the earliest document is the
    // one that introduces a concept, and later mentions describe it in
    // passing. Overwriting would replace a definition with an aside.
    if (!entry.description && c.description) entry.description = c.description;
    if (!entry.chapter && c.chapter) entry.chapter = c.chapter;
    if (!entry.section_id && c.section_id) entry.section_id = c.section_id;
    if (c.source_file && !entry.sources.includes(c.source_file)) entry.sources.push(c.source_file);
    if (c.source_title && !entry.titles.includes(c.source_title)) entry.titles.push(c.source_title);
  }
}

let concepts = [...byKey.values()];
const merged = candidates - concepts.length;

// The cap is the Content Admin's, and a list over it would be refused on
// arrival — after every call had been paid for. Cut by how many documents
// mention a concept: something three works discuss belongs in a course map
// more than something one paragraph names in passing.
let dropped = 0;
if (concepts.length > plan.MAX_CONCEPTS) {
  concepts.sort((a, b) => (b.sources.length - a.sources.length)
                       || (b.mentions - a.mentions)
                       || a.name.localeCompare(b.name));
  dropped = concepts.length - plan.MAX_CONCEPTS;
  concepts = concepts.slice(0, plan.MAX_CONCEPTS);
}

// Back into reading order, which is what the prerequisite pass needs: where
// something appears in the course is the strongest evidence there is about
// what comes before what.
concepts.sort((a, b) =>
  String(a.chapter || '').localeCompare(String(b.chapter || ''), undefined, { numeric: true })
  || String(a.section_id || '').localeCompare(String(b.section_id || ''), undefined, { numeric: true })
  || a.name.localeCompare(b.name));

if (!concepts.length) {
  throw new Error('No concepts were found in any of the material. Either the ' +
                  'documents hold no teaching content, or every extraction ' +
                  'call came back empty.');
}

return [{ json: { concepts, stats: { candidates, merged, dropped,
                                     concepts: concepts.length,
                                     slices: items.length } } }];

// ── One text completion, against whichever provider is configured ──────────
// The same six-way dispatch as content-admin/llm_client.py and the image
// description in ingest-document.json — same endpoints, headers and auth,
// text only. Copied rather than imported because n8n Code nodes cannot share
// a module; kept identical so a provider that works for one feature works for
// all of them.
async function complete(systemPrompt, userPrompt, maxTokens) {
  const provider = ($env.LLM_PROVIDER || '').trim();
  const apiKey   = $env.LLM_API_KEY || '';
  const model    = $env.LLM_MODEL_STRONG || '';
  const baseUrl  = $env.LLM_BASE_URL || '';
  // No fallback: calling a different vendor than the configured one produces
  // an auth error that points away from the real problem, an empty variable.
  if (!provider) throw new Error('LLM_PROVIDER is empty in .env.');
  if (!apiKey)   throw new Error('LLM_API_KEY is empty in .env.');
  if (!model)    throw new Error('LLM_MODEL_STRONG is empty in .env.');

  let url, headers, body, extractText, finishReason;

  if (provider === 'anthropic') {
    url = 'https://api.anthropic.com/v1/messages';
    headers = { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' };
    body = { model, max_tokens: maxTokens, system: systemPrompt,
             messages: [{ role: 'user', content: userPrompt }] };
    extractText  = (d) => (d.content || []).find(b => b.type === 'text')?.text || '';
    finishReason = (d) => d.stop_reason || '';
  } else if (provider === 'google') {
    url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`;
    headers = { 'x-goog-api-key': apiKey, 'Content-Type': 'application/json' };
    body = { systemInstruction: { parts: [{ text: systemPrompt }] },
             contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
             generationConfig: { maxOutputTokens: maxTokens } };
    extractText  = (d) => d?.candidates?.[0]?.content?.parts?.[0]?.text || '';
    finishReason = (d) => d?.candidates?.[0]?.finishReason || '';
  } else if (provider === 'cohere') {
    url = 'https://api.cohere.com/v2/chat';
    headers = { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' };
    body = { model, max_tokens: maxTokens, stream: false,
             messages: [{ role: 'system', content: systemPrompt },
                        { role: 'user', content: userPrompt }] };
    extractText  = (d) => d?.message?.content?.[0]?.text || '';
    finishReason = (d) => d?.finish_reason || '';
  } else {
    if (provider === 'openai') url = 'https://api.openai.com/v1/chat/completions';
    else if (provider === 'mistral') url = 'https://api.mistral.ai/v1/chat/completions';
    else if (provider === 'openrouter') url = 'https://openrouter.ai/api/v1/chat/completions';
    else if (provider === 'custom') url = `${(baseUrl || '').replace(/\/$/, '')}/chat/completions`;
    else throw new Error(`Unknown LLM_PROVIDER: ${provider}`);
    headers = { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' };
    body = { model, messages: [{ role: 'system', content: systemPrompt },
                               { role: 'user', content: userPrompt }] };
    // OpenAI rejects max_tokens outright on current models; the others still
    // want it. Same split as llm_client.py.
    if (provider === 'openai') body.max_completion_tokens = maxTokens;
    else body.max_tokens = maxTokens;
    extractText  = (d) => d?.choices?.[0]?.message?.content || '';
    finishReason = (d) => d?.choices?.[0]?.finish_reason || '';
  }

  const raw = await this.helpers.request({ method: 'POST', url, headers,
                                           body: JSON.stringify(body), json: false });
  const data = JSON.parse(raw);
  const text = (extractText(data) || '').trim();
  if (!text) {
    // An empty answer is a failure where it happens. Measured on the test
    // installation: a reasoning model spent the whole budget thinking and
    // returned an empty string with finish_reason "length", which the API
    // calls a success — and the emptiness was then reported several layers
    // away as something that had not happened.
    const why = finishReason(data) || 'not stated';
    throw new Error(`The model returned an empty answer (finish reason: ${why}). ` +
      (/len|max_token/i.test(why)
        ? `The budget of ${maxTokens} tokens was spent before any text was written.`
        : ''));
  }
  return text;
}

// Models wrap JSON in a fence often enough that stripping it is leniency
// about the wrapper, not about the format.
function parseJson(text, what) {
  let raw = text.trim();
  const fence = raw.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/);
  if (fence) raw = fence[1];
  try {
    return JSON.parse(raw);
  } catch (e) {
    throw new Error(`${what}: the model did not return valid JSON (${e.message}). ` +
                    `First 200 characters: ${raw.slice(0, 200)}`);
  }
}

// -- One pass over the whole vocabulary: what has to come before what -------
// The only step that needs a global view, and the reason the corpus never has
// to fit in a prompt: this reads the *concept list*, not the material. Five
// hundred concepts with a name, a chapter and a sentence each is about 60k
// characters -- one call, and it costs the same for forty documents as for
// four.
const plan     = $('Plan the run').first().json;
const incoming = $input.first().json;
const concepts = incoming.concepts;

const listing = concepts.map((c, i) => {
  const where = [c.chapter, c.section_id].filter(Boolean).join(' ');
  const from  = c.titles.slice(0, 3).join('; ');
  return `${i + 1}. ${c.name}${where ? ` (${where})` : ''}\n` +
         `   ${c.description || '-'}\n   in: ${from}`;
}).join('\n');

const systemPrompt =
  'You lay out the order in which concepts of a university course have to be ' +
  'learned. You answer with JSON and nothing else: no explanation, no ' +
  'commentary, no code fence.';

const userPrompt =
  `These are the concepts of the course "${plan.courseName}", in the order ` +
  'they appear in its material, each with the works it comes from.\n\n' +
  'Name the pairs where one concept has to be understood *before* another ' +
  'can be. Only real dependencies: "B cannot be grasped without A". Not ' +
  '"they are related", not "they appear in the same chapter", not "A is ' +
  'mentioned first".\n\n' +
  'For each pair give "before", "after" -- both exactly as spelled in the ' +
  'list -- and "sources", the work or works that justify the dependency, ' +
  'named exactly as they appear after "in:". Every pair must cite at least ' +
  'one. If no material supports a dependency you suspect, leave it out: an ' +
  'edge nobody can check is worse than a gap somebody can see.\n\n' +
  'Prerequisites form no cycles. If two concepts seem to require each other, ' +
  'pick the direction the material teaches and drop the other.\n\n' +
  'Answer exactly:\n' +
  '{"prerequisites": [{"before": "...", "after": "...", "sources": ["..."]}]}\n\n' +
  `--- Concepts ---\n${listing}\n--- end ---`;

const answer = await complete.call(this, systemPrompt, userPrompt, 16384);
const parsed = parseJson(answer, 'Proposing prerequisites');

// Names back to their exact spelling, and titles back to file paths. The
// model was asked about things it can read; the graph stores paths, and a
// citation that does not resolve to a real document is refused on arrival --
// so it is resolved here, where the mapping exists, rather than sent to be
// rejected after every call has been paid for.
const byName  = new Map(concepts.map(c => [c.name.toLowerCase(), c]));
const byTitle = new Map();
for (const c of concepts) {
  c.titles.forEach((t, i) => {
    if (!byTitle.has(t.toLowerCase())) byTitle.set(t.toLowerCase(), c.sources[i] || c.sources[0]);
  });
}

const proposed = [];
const seen = new Set();
let unresolved = 0, uncited = 0;

for (const e of (parsed.prerequisites || [])) {
  const a = byName.get(String(e && e.before ? e.before : '').trim().toLowerCase());
  const b = byName.get(String(e && e.after ? e.after : '').trim().toLowerCase());
  // An edge naming a concept that is not in the list writes nothing and
  // reports success, which is how a map ends up looking complete and
  // answering nothing.
  if (!a || !b || a === b) { unresolved++; continue; }
  const key = `${a.name} >> ${b.name}`;
  if (seen.has(key)) continue;

  const raw = Array.isArray(e && e.sources) ? e.sources : [e && e.sources];
  const cited = [];
  for (const s of raw) {
    const file = byTitle.get(String(s == null ? '' : s).trim().toLowerCase());
    if (file && !cited.includes(file)) cited.push(file);
  }
  // Every edge must cite material that exists. This does not make an edge
  // correct; it removes the edges no document supports, which between two
  // unrelated subjects is all of them.
  if (!cited.length) { uncited++; continue; }

  seen.add(key);
  proposed.push({ before: a.name, after: b.name, sources: cited });
}

// Cycles. The model was asked not to make them and sometimes will anyway, and
// the Content Admin refuses a whole proposal that contains one -- so a single
// loop would waste the entire build. Break them here, on the edge that closes
// the loop, and report how many were dropped rather than hiding it.
const built = new Map();
const wouldClose = (from, to) => {
  const stack = [to];
  const visited = new Set();
  while (stack.length) {
    const n = stack.pop();
    if (n === from) return true;
    if (visited.has(n)) continue;
    visited.add(n);
    for (const next of (built.get(n) || [])) stack.push(next);
  }
  return false;
};

const kept = [];
let cyclic = 0;
for (const e of proposed) {
  if (wouldClose(e.before, e.after)) { cyclic++; continue; }
  if (!built.has(e.before)) built.set(e.before, []);
  built.get(e.before).push(e.after);
  kept.push(e);
}

const proposal = {
  concepts: concepts.map(c => {
    const out = { name: c.name, sources: c.sources };
    if (c.description) out.description = c.description;
    if (c.chapter) out.chapter = c.chapter;
    if (c.section_id) out.section_id = c.section_id;
    return out;
  }),
  prerequisites: kept,
};

return [{ json: {
  buildId: plan.buildId, adminUrl: plan.adminUrl, proposal,
  stats: Object.assign({}, incoming.stats, {
    edges: kept.length,
    edges_unresolved: unresolved,
    edges_uncited: uncited,
    edges_cyclic: cyclic,
    documents: new Set(concepts.reduce((a, c) => a.concat(c.sources), [])).size,
  }),
} }];

// What failed, and which build to report it against.
//
// The error item is n8n's shape, not this workflow's, and the build id lives
// in the webhook body that started the execution. Without it the Content
// Admin has a row saying "running" that nothing will ever finish -- which is
// the state this whole path exists to prevent.
const e = $input.first().json || {};
const body = e.execution?.data?.resultData?.runData?.['Build Webhook']?.[0]
              ?.data?.main?.[0]?.[0]?.json?.body
          || e.workflow?.body
          || {};
const buildId = (body.build_id || '').trim();
const message = (e.execution?.error?.message)
             || (e.error?.message)
             || 'The build failed and n8n gave no message.';
const node = e.execution?.lastNodeExecuted || e.execution?.error?.node?.name || '';

return [{ json: {
  buildId,
  reportable: Boolean(buildId),
  error: node ? `${node}: ${message}` : message,
} }];
